import{_ as s,o as t,c as a,a2 as r}from"./chunks/framework.DqYch1Cg.js";const m=JSON.parse('{"title":"NestJS 基础认知与选型","description":"","frontmatter":{},"headers":[],"relativePath":"学习自测/18nestjs/q_nestjs_5-basics.md","filePath":"学习自测/18nestjs/q_nestjs_5-basics.md","lastUpdated":1794211306000}'),o={name:"学习自测/18nestjs/q_nestjs_5-basics.md"};function n(p,e,i,_,c,l){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="nestjs-基础认知与选型" tabindex="-1">NestJS 基础认知与选型 <a class="header-anchor" href="#nestjs-基础认知与选型" aria-label="Permalink to &quot;NestJS 基础认知与选型&quot;">​</a></h1><blockquote><p>结合学习过程整理的基础面试问答，以口语化表达讲清核心概念和选型理由。 扩展阅读：<a href="/FE-prepare-interview/概念与原理/18nestjs/s_nestjs_1-overview">NestJS 概览</a>。</p></blockquote><h2 id="_1-能简单介绍一下-nestjs-吗-为什么选择它" tabindex="-1">1. 能简单介绍一下 NestJS 吗？为什么选择它？ <a class="header-anchor" href="#_1-能简单介绍一下-nestjs-吗-为什么选择它" aria-label="Permalink to &quot;1. 能简单介绍一下 NestJS 吗？为什么选择它？&quot;">​</a></h2><details class="details custom-block"><summary>参考回答</summary><p>NestJS 是基于 Node.js、主要用 TypeScript 开发的后端框架。</p><p>Express、Koa 更轻量、更灵活，但模块怎么拆、依赖怎么管理，通常要团队自己约定。项目规模大了，如果缺少统一规范，维护成本就会上来。</p><p>NestJS 提供了比较完整的工程约定：用 Module 划分业务模块，Controller 接收请求，Service 处理业务，再通过依赖注入把它们组织起来，方便解耦和测试。像权限控制、参数校验、日志这些通用逻辑，也有 Guard、Pipe、Interceptor 等机制来承接。数据库操作则可以结合 TypeORM 或 Prisma。</p><p>对我来说，前端的 TypeScript 经验可以复用，学习后端时能减少语言切换成本。而且我希望掌握更系统的后端开发方式，所以选择学习 NestJS。</p></details><p><strong>回答节奏</strong>：这道开场题控制在一分钟左右，三分钟作为上限。讲完框架特点可以稍停一下，给面试官接话的机会；没有追问，再补充自己的学习动机。</p><p><strong>追问入口</strong>：你提到依赖注入，它具体解决了什么问题？可结合<a href="./q_nestjs_2-module_di">模块与 DI 实战</a>继续复习。</p><h2 id="_2-nestjs-中的-ioc、di、aop-分别是什么" tabindex="-1">2. NestJS 中的 IoC、DI、AOP 分别是什么？ <a class="header-anchor" href="#_2-nestjs-中的-ioc、di、aop-分别是什么" aria-label="Permalink to &quot;2. NestJS 中的 IoC、DI、AOP 分别是什么？&quot;">​</a></h2><details class="details custom-block"><summary>参考回答</summary><p><strong>IoC 是控制反转，DI 是依赖注入，AOP 是面向切面编程。</strong></p><p>IoC 是一种思想。拿依赖管理来说，以前是业务类自己 <code>new</code> 依赖，现在交给 NestJS 容器创建和管理，这就是控制权的反转。</p><p>DI 是实现 IoC 的一种常见方式。比如 Controller 需要 Service，我们注册好 Provider，再通过构造函数注入，就不用自己创建了，也方便替换实现和做单元测试。</p><p>AOP 主要是把日志、耗时统计这些通用逻辑从业务里抽出来。比如用 Interceptor 在请求处理前后统一加逻辑，就不用每个接口都重复写。</p><p><strong>简单说，IoC 是把依赖管理交给容器，DI 是容器把依赖提供给你，AOP 是把通用逻辑和业务逻辑分开。</strong></p></details><p><strong>回答节奏</strong>：控制在一分钟左右，讲完三个概念后可以稍停，最后一句用于收尾。</p><p><strong>追问入口</strong>：NestJS 怎么知道该给你注入哪个依赖？可结合<a href="./q_nestjs_2-module_di">模块与 DI 实战</a>和<a href="/FE-prepare-interview/概念与原理/18nestjs/s_nestjs_6-interceptor_pipe">拦截器与管道</a>继续复习。</p>',10)])])}const u=s(o,[["render",n]]);export{m as __pageData,u as default};
